def isMonotonic(A):
    if len(A) <= 2:
        return True
    i = 1
    while i < len(A) and A[i] == A[i - 1]:
        i += 1
    if i == len(A):
        return True
    increasing = decreasing = True
    while i < len(A):
        if A[i] > A[i - 1]:
            decreasing = False
        elif A[i] < A[i - 1]:
            increasing = False
        if not increasing and not decreasing:
            return False
        i += 1
    return True
```
</solution>

